package com.getlancer;
import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import static com.getlancer.Support.*;
@RestController @RequestMapping("/api/v1") class ProductsController{
 @org.springframework.beans.factory.annotation.Value("${app.reliability-min-sample:10}") int reliabilityMinimum=10;
 final JdbcTemplate db;final Security security;final Mail mail;ProductsController(JdbcTemplate db,Security security,Mail mail){this.db=db;this.security=security;this.mail=mail;}
 static final String PUBLIC="p.approval_status='APPROVED' AND p.lifecycle_status='ACTIVE' AND p.visibility='PUBLIC' AND u.account_status='ACTIVE' AND d.approval_status='APPROVED'";
 static final String SELECT="SELECT p.*,d.display_name AS builder,d.slug AS builder_slug,d.availability_status AS availability,d.booked_until,u.account_status AS owner_status,d.approval_status AS profile_status FROM products p JOIN users u ON u.id=p.owner_user_id JOIN developer_profiles d ON d.user_id=u.id";
 Map<String,Object> dto(Map<String,Object> p){return dto(p,db.queryForList("SELECT id,alt_text FROM product_media WHERE product_id=? AND verified=true ORDER BY sort_order,created_at,id LIMIT 6",p.get("id")));}
 List<Map<String,Object>> dtos(List<Map<String,Object>> rows){if(rows.isEmpty())return List.of();var ids=rows.stream().map(p->p.get("id")).toArray();var media=db.queryForList("SELECT id,product_id,alt_text FROM product_media WHERE verified=true AND product_id IN ("+String.join(",",Collections.nCopies(ids.length,"?"))+") ORDER BY sort_order,created_at,id",ids);Map<Object,List<Map<String,Object>>> grouped=new HashMap<>();for(var m:media)grouped.computeIfAbsent(m.get("product_id"),k->new ArrayList<>()).add(m);return rows.stream().map(p->dto(p,grouped.getOrDefault(p.get("id"),List.of()))).toList();}
 Map<String,Object> dto(Map<String,Object> p,List<Map<String,Object>> media){Map<String,Object> x=new LinkedHashMap<>();for(String k:List.of("id","slug","title","summary","description","category","technology","builder","availability","visibility"))x.put(k,p.get(k));x.put("bookedUntil",p.get("booked_until"));String[] old={"builder_slug","project_type","contribution_text","live_url","video_url","approval_status","lifecycle_status","available_for_similar_work","updated_at","moderation_reason","repository_url","pricing_note","rights_confirmed"};String[] keys={"builderSlug","projectType","contribution","liveUrl","videoUrl","approvalStatus","lifecycleStatus","availableForSimilarWork","updatedAt","moderationReason","repositoryUrl","pricingNote","rightsConfirmed"};for(int n=0;n<old.length;n++)x.put(keys[n],p.get(old[n]));if(!media.isEmpty())x.put("imageUrl","/api/v1/media/"+media.get(0).get("id")+"?variant=thumbnail");x.put("media",media.stream().map(m->Map.of("id",m.get("id"),"url","/api/v1/media/"+m.get("id"),"alt",Objects.toString(m.get("alt_text"),"Project screenshot"))).toList());return x;}
 @GetMapping("/products") Map<String,Object> search(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String category,@RequestParam(defaultValue="")String technology,@RequestParam(defaultValue="")String projectType,@RequestParam(defaultValue="")String availability,@RequestParam(defaultValue="")String builder,@RequestParam(defaultValue="false")boolean liveDemo,@RequestParam(defaultValue="newest")String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(q.length()>200||page<0||page>10000||size<1||size>100)throw new ApiError(400,"VALIDATION_ERROR","Invalid search or pagination.");String sql=" WHERE "+PUBLIC;List<Object>a=new ArrayList<>();if(!builder.isBlank()){sql+=" AND d.slug=?";a.add(builder);}if(!q.isBlank()){sql+=" AND (to_tsvector('english',p.title||' '||p.summary||' '||p.description||' '||p.category||' '||p.technology) @@ websearch_to_tsquery('english',?) OR p.title ILIKE ? OR d.display_name ILIKE ?)";a.add(q);a.add("%"+q.replace("%","\\%").replace("_","\\_")+"%");a.add("%"+q.replace("%","\\%").replace("_","\\_")+"%");}for(var e:Map.of("p.category",category,"p.project_type",projectType,"d.availability_status",availability).entrySet())if(!e.getValue().isBlank()){sql+=" AND "+e.getKey()+"=?";a.add(e.getValue());}if(!technology.isBlank()){sql+=" AND ?=ANY(string_to_array(p.technology,','))";a.add(technology);}if(liveDemo)sql+=" AND p.live_url IS NOT NULL AND p.live_url<>''";Long total=db.queryForObject("SELECT count(*) FROM products p JOIN users u ON u.id=p.owner_user_id JOIN developer_profiles d ON d.user_id=u.id"+sql,Long.class,a.toArray());String order="p.created_at DESC,p.id";if(sort.equals("updated"))order="p.updated_at DESC,p.id";if(sort.equals("relevance")&&!q.isBlank()){order="CASE WHEN p.title ILIKE ? THEN 0 ELSE 1 END,p.updated_at DESC,p.id";a.add("%"+q+"%");}a.add(size);a.add(page*size);var rows=db.queryForList(SELECT+sql+" ORDER BY "+order+" LIMIT ? OFFSET ?",a.toArray());return Map.of("items",dtos(rows),"page",page,"size",size,"totalItems",total,"totalPages",(total+size-1)/size);}
 @GetMapping("/products/{slug}") Map<String,Object> detail(@PathVariable String slug){var rows=db.queryForList(SELECT+" WHERE p.slug=? AND "+PUBLIC,slug);if(rows.isEmpty())throw new ApiError(404,"NOT_FOUND","Project not found.");return dto(rows.get(0));}
 @GetMapping("/builders/{slug}") Map<String,Object> builder(@PathVariable String slug){var rows=db.queryForList("SELECT d.user_id AS id,d.display_name AS \"displayName\",d.headline,d.bio,d.technology,d.category,d.availability_status AS \"availabilityStatus\",d.booked_until AS \"bookedUntil\",d.github_url AS \"githubUrl\",d.linkedin_url AS \"linkedinUrl\",d.website_url AS \"websiteUrl\",d.country,d.time_zone AS \"timeZone\",d.languages FROM developer_profiles d JOIN users u ON u.id=d.user_id WHERE d.slug=? AND d.approval_status='APPROVED' AND u.account_status='ACTIVE'",slug);if(rows.isEmpty())throw new ApiError(404,"NOT_FOUND","Builder not found.");var profile=new LinkedHashMap<>(rows.get(0));var metric=db.queryForMap("SELECT count(*) AS sample,count(first_response) AS responded,percentile_cont(0.5) WITHIN GROUP(ORDER BY extract(epoch FROM (first_response-email_confirmed_at))/3600) AS median_hours FROM (SELECT i.email_confirmed_at,(SELECT min(e.created_at) FROM inquiry_events e WHERE e.inquiry_id=i.id AND e.event_type='RESPONDED') AS first_response FROM inquiries i WHERE i.developer_user_id=? AND i.moderation_status='CLEAR' AND i.email_confirmed_at<now()-interval '48 hours') q",profile.get("id"));long sample=((Number)metric.get("sample")).longValue();
 if(reliabilityMinimum>0&&sample>=reliabilityMinimum){profile.put("responseSample",sample);profile.put("responseRate",100.0*((Number)metric.get("responded")).longValue()/sample);profile.put("medianResponseHours",metric.get("median_hours"));}return profile;}
 @GetMapping("/builders/{slug}/reviews") Map<String,Object> reviews(@PathVariable String slug,HttpServletRequest r){return Pages.query(db,r,"SELECT r.id,r.rating,r.review_text AS \"reviewText\",r.created_at AS \"createdAt\",CASE WHEN r.visibility='NAMED' THEN (SELECT i.client_name FROM inquiries i WHERE i.id=r.inquiry_id) ELSE 'Verified client' END AS \"clientName\" FROM reviews r JOIN developer_profiles d ON d.user_id=r.developer_user_id JOIN users u ON u.id=d.user_id WHERE d.slug=? AND d.approval_status='APPROVED' AND u.account_status='ACTIVE' AND r.moderation_status='PUBLISHED' AND EXISTS(SELECT 1 FROM inquiries i WHERE i.id=r.inquiry_id AND i.moderation_status='CLEAR') ORDER BY r.created_at DESC,r.id",slug);}
 @PutMapping("/developer/profile") @Transactional Map<String,Object> profile(@RequestBody Map<String,Object>b,HttpServletRequest r){UUID u=security.developer(r,false);var previous=db.queryForMap("SELECT * FROM developer_profiles WHERE user_id=? FOR UPDATE",u);if(previous.get("approval_status").equals("SUSPENDED"))throw new ApiError(403,"FORBIDDEN","This profile is suspended.");String availability=text(b,"availabilityStatus",1,30);if(!Set.of("AVAILABLE_NOW","ONE_SLOT_LEFT","LIMITED","BOOKED_UNTIL","NOT_ACCEPTING").contains(availability))throw new ApiError(400,"VALIDATION_ERROR","Choose a valid availability.");var details=ProfileDetails.read(b,previous);java.sql.Date date=details.bookedUntil(b,availability);String github=text(b,"githubUrl",0,500),linkedin=text(b,"linkedinUrl",0,500);Rules.safeUrl(github);Rules.safeUrl(linkedin);db.update("UPDATE developer_profiles SET display_name=?,headline=?,bio=?,technology=?,category=?,availability_status=?,booked_until=?,github_url=?,linkedin_url=?,updated_at=now() WHERE user_id=?",text(b,"displayName",2,100),text(b,"headline",5,160),text(b,"bio",20,3000),text(b,"technology",1,300),text(b,"category",1,200),availability,date,github,linkedin,u);db.update("UPDATE developer_profiles SET website_url=?,country=?,time_zone=?,languages=? WHERE user_id=?",details.websiteUrl(),details.country(),details.timeZone(),details.languages(),u);boolean material=details.changed(previous)||!text(b,"displayName",2,100).equals(previous.get("display_name"))||!text(b,"headline",5,160).equals(previous.get("headline"))||!text(b,"bio",20,3000).equals(previous.get("bio"))||!text(b,"technology",1,300).equals(previous.get("technology"))||!text(b,"category",1,200).equals(previous.get("category"))||!github.equals(Objects.toString(previous.get("github_url"),""))||!linkedin.equals(Objects.toString(previous.get("linkedin_url"),""));if(material&&Set.of("APPROVED","PROFILE_PENDING").contains(previous.get("approval_status")))db.update("UPDATE developer_profiles SET approval_status='DRAFT' WHERE user_id=?",u);return Map.of("ok",true);}
 @PostMapping("/developer/profile/submit") @Transactional Map<String,Object> submitProfile(HttpServletRequest r){UUID u=security.developer(r,false);var p=db.queryForMap("SELECT d.*,u.email_verified_at FROM developer_profiles d JOIN users u ON u.id=d.user_id WHERE d.user_id=? FOR UPDATE",u);if(p.get("email_verified_at")==null)throw new ApiError(409,"EMAIL_NOT_VERIFIED","Confirm your email first.");if(!Set.of("DRAFT","CHANGES_REQUESTED").contains(p.get("approval_status")))throw new ApiError(409,"INVALID_STATE_TRANSITION","Profile cannot be submitted now.");for(String k:List.of("display_name","headline","bio","technology","category"))if(Objects.toString(p.get(k),"").isBlank())throw new ApiError(400,"VALIDATION_ERROR","Complete your profile first.");db.update("UPDATE developer_profiles SET approval_status='PROFILE_PENDING' WHERE user_id=?",u);return Map.of("ok",true);}
 @GetMapping("/developer/products") Map<String,Object> own(HttpServletRequest r){UUID u=security.developer(r,false);String sql=SELECT+" WHERE p.owner_user_id=?";List<Object> args=new ArrayList<>();args.add(u);
  for(String key:List.of("lifecycleStatus","approvalStatus")){String value=Objects.toString(r.getParameter(key),"");if(value.isBlank())continue;
   Set<String> values=key.equals("lifecycleStatus")?Set.of("DRAFT","ACTIVE","ARCHIVED","SUSPENDED"):Set.of("DRAFT","PENDING_REVIEW","CHANGES_REQUESTED","APPROVED","REJECTED","SUSPENDED");
   if(!values.contains(value))throw new ApiError(400,"VALIDATION_ERROR","Choose a valid showcase state.");
   sql+=key.equals("lifecycleStatus")?" AND p.lifecycle_status=?":" AND p.approval_status=?";args.add(value);
  }
  var result=Pages.query(db,r,sql+" ORDER BY p.updated_at DESC,p.id",args.toArray());result.put("totalOwned",db.queryForObject("SELECT count(*) FROM products WHERE owner_user_id=?",Integer.class,u));result.put("items",dtos(Pages.items(result)));result.put("activeCount",db.queryForObject("SELECT count(*) FROM products WHERE owner_user_id=? AND lifecycle_status='ACTIVE'",Integer.class,u));return result;}
 @PostMapping("/developer/products") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @Transactional Map<String,Object> create(@RequestBody Map<String,Object>b,HttpServletRequest r){UUID u=security.developer(r,true),p=id();String title=text(b,"title",3,120);db.update("INSERT INTO products(id,owner_user_id,slug,title,summary,description,project_type,category,technology,contribution_text) VALUES(?,?,?,?,?,?,?,?,?,?)",p,u,title.toLowerCase().replaceAll("[^a-z0-9]+","-")+"-"+p.toString().substring(0,8),title,"","","PERSONAL","","","");save(p,b,u);return Map.of("id",p);}
 @PatchMapping("/developer/products/{id}") @Transactional Map<String,Object> edit(@PathVariable UUID id,@RequestBody Map<String,Object>b,HttpServletRequest r){UUID u=security.developer(r,true);owned(id,u);save(id,b,u);return Map.of("ok",true);}
 void save(UUID p,Map<String,Object>b,UUID u){String category=text(b,"category",1,100);if(db.queryForObject("SELECT count(*) FROM categories WHERE name=? AND active=true",Integer.class,category)==0)throw new ApiError(400,"VALIDATION_ERROR","Choose an active business category.");String technology=text(b,"technology",0,300);Set<String> techs=new LinkedHashSet<>();for(String t:technology.split(","))if(!t.isBlank()){t=t.trim();if(db.queryForObject("SELECT count(*) FROM technologies WHERE name=? AND active=true",Integer.class,t)==0)throw new ApiError(400,"VALIDATION_ERROR","Choose active technology tags.");techs.add(t);}technology=String.join(",",techs);String live=text(b,"liveUrl",0,1000),video=text(b,"videoUrl",0,1000);Rules.safeUrl(live);Rules.safeUrl(video);String repository=text(b,"repositoryUrl",0,1000),pricing=text(b,"pricingNote",0,300);Rules.safeUrl(repository);String type=text(b,"projectType",1,40),visibility=text(b,"visibility",1,30);if(!Set.of("COMMERCIAL","CLIENT","SAAS","PERSONAL","OPEN_SOURCE","PROTOTYPE","HACKATHON","LEARNING","PRIVATE_CASE_STUDY","NDA_CONFIDENTIAL").contains(type)||!Set.of("PUBLIC","PRIVATE_CASE_STUDY","NDA_SAFE").contains(visibility))throw new ApiError(400,"VALIDATION_ERROR","Choose a valid project type and visibility.");db.update("UPDATE products SET title=?,summary=?,description=?,project_type=?,category=?,technology=?,visibility=?,contribution_text=?,live_url=?,video_url=?,available_for_similar_work=?,rights_confirmed=?,approval_status='DRAFT',lifecycle_status='DRAFT',updated_at=now() WHERE id=? AND owner_user_id=?",text(b,"title",3,120),text(b,"summary",5,240),text(b,"description",20,10000),type,category,technology,visibility,text(b,"contribution",10,3000),live,video,Boolean.TRUE.equals(b.get("availableForSimilarWork")),Boolean.TRUE.equals(b.get("rightsConfirmed")),p,u);db.update("UPDATE products SET repository_url=?,pricing_note=? WHERE id=?",repository,pricing,p);db.update("DELETE FROM product_categories WHERE product_id=?",p);db.update("INSERT INTO product_categories SELECT ?,slug FROM categories WHERE name=?",p,category);db.update("DELETE FROM product_technologies WHERE product_id=?",p);for(String t:techs)db.update("INSERT INTO product_technologies SELECT ?,slug FROM technologies WHERE name=?",p,t);}
 Map<String,Object> owned(UUID p,UUID u){var rows=db.queryForList("SELECT * FROM products WHERE id=? AND owner_user_id=? FOR UPDATE",p,u);if(rows.isEmpty())throw new ApiError(404,"NOT_FOUND","Project not found.");if(rows.get(0).get("approval_status").equals("SUSPENDED"))throw new ApiError(403,"FORBIDDEN","This project is suspended.");return rows.get(0);}
 @PostMapping("/developer/products/{id}/{action}") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) @Transactional Map<String,Object> action(@PathVariable UUID id,@PathVariable String action,HttpServletRequest r){UUID u=security.developer(r,true);db.queryForMap("SELECT * FROM showcase_entitlements WHERE user_id=? FOR UPDATE",u);var p=owned(id,u);switch(action){case "submit"->{if(!Set.of("DRAFT","CHANGES_REQUESTED").contains(p.get("approval_status")))throw new ApiError(409,"INVALID_STATE_TRANSITION","Project cannot be submitted now.");if(!Boolean.TRUE.equals(p.get("rights_confirmed")))throw new ApiError(400,"VALIDATION_ERROR","Confirm your right to showcase this work.");if(p.get("visibility").equals("PUBLIC")&&db.queryForObject("SELECT count(*) FROM product_media WHERE product_id=? AND verified=true",Integer.class,id)==0&&Objects.toString(p.get("video_url"),"").isBlank()&&Objects.toString(p.get("live_url"),"").isBlank())throw new ApiError(400,"VALIDATION_ERROR","Add a proof image, demo video or live demo before submitting.");db.update("UPDATE products SET approval_status='PENDING_REVIEW',updated_at=now() WHERE id=?",id);}case "archive"->{if(!Set.of("ACTIVE","ARCHIVED").contains(p.get("lifecycle_status")))throw new ApiError(409,"INVALID_STATE_TRANSITION","Only an active showcase can be archived.");if(p.get("lifecycle_status").equals("ACTIVE")){db.update("UPDATE products SET lifecycle_status='ARCHIVED',updated_at=now() WHERE id=?",id);db.update("INSERT INTO analytics_events(id,event_name,entity_id) VALUES(?,'product_archived',?)",id(),id);}}case "activate"->activate(id,u,true);default->throw new ApiError(404,"NOT_FOUND","Action not found.");}return Map.of("ok",true);}
 void activate(UUID p,UUID u,boolean fail){var ent=db.queryForMap("SELECT * FROM showcase_entitlements WHERE user_id=? FOR UPDATE",u);var product=db.queryForMap("SELECT * FROM products WHERE id=? FOR UPDATE",p);if(!product.get("approval_status").equals("APPROVED"))throw new ApiError(409,"INVALID_STATE_TRANSITION","Product approval is required.");if(product.get("lifecycle_status").equals("ACTIVE"))return;boolean approved=db.queryForObject("SELECT count(*) FROM developer_profiles d JOIN users u ON u.id=d.user_id WHERE d.user_id=? AND d.approval_status='APPROVED' AND u.account_status='ACTIVE' AND u.email_verified_at IS NOT NULL",Integer.class,u)>0;int count=db.queryForObject("SELECT count(*) FROM products WHERE owner_user_id=? AND lifecycle_status='ACTIVE'",Integer.class,u);if(!Rules.canActivate(true,approved,count,(Integer)ent.get("active_slot_limit"))){if(fail)throw new ApiError(409,"SLOT_LIMIT_REACHED","Archive an active showcase to make room.");return;}db.update("UPDATE products SET lifecycle_status='ACTIVE',updated_at=now() WHERE id=?",p);db.update("INSERT INTO analytics_events(id,event_name,entity_id) VALUES(?,'product_activated',?)",id(),p);}
 @PostMapping("/products/{id}/save") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) @Transactional Map<String,Object> saveProduct(@PathVariable UUID id,HttpServletRequest r){UUID u=security.user(r);if(db.queryForList(SELECT+" WHERE p.id=? AND "+PUBLIC,id).isEmpty())throw new ApiError(404,"NOT_FOUND","Project unavailable.");if(db.update("INSERT INTO saved_products(user_id,product_id) VALUES(?,?) ON CONFLICT DO NOTHING",u,id)>0)db.update("INSERT INTO analytics_events(id,event_name,entity_id) VALUES(?,'product_saved',?)",Support.id(),id);return Map.of("ok",true);}
 @DeleteMapping("/products/{id}/save") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) @Transactional Map<String,Object> unsave(@PathVariable UUID id,HttpServletRequest r){if(db.update("DELETE FROM saved_products WHERE user_id=? AND product_id=?",security.user(r),id)>0)db.update("INSERT INTO analytics_events(id,event_name,entity_id) VALUES(?,'product_unsaved',?)",Support.id(),id);return Map.of("ok",true);}
 @GetMapping("/me/saved-products") Map<String,Object> saved(HttpServletRequest r){UUID u=security.user(r);String sql=SELECT+" JOIN saved_products s ON s.product_id=p.id WHERE s.user_id=?";List<Object> args=new ArrayList<>();args.add(u);
  String ids=Objects.toString(r.getParameter("ids"),"");if(!ids.isBlank()){String[] selected=ids.split(",",-1);if(selected.length>50)throw new ApiError(400,"VALIDATION_ERROR","Select at most 50 projects.");sql+=" AND p.id IN ("+String.join(",",Collections.nCopies(selected.length,"?"))+")";for(String value:selected)args.add(uuid(value));}
  var result=Pages.query(db,r,sql+" ORDER BY s.created_at DESC,p.id",args.toArray());result.put("items",Pages.items(result).stream().map(p->{boolean visible=Rules.publicProduct((String)p.get("approval_status"),(String)p.get("lifecycle_status"),(String)p.get("visibility"),(String)p.get("owner_status"),(String)p.get("profile_status"));return visible?Map.of("id",p.get("id"),"title",p.get("title"),"summary",p.get("summary"),"slug",p.get("slug"),"available",true):Map.of("id",p.get("id"),"available",false);}).toList());return result;}
 @GetMapping("/categories") Map<String,Object> categories(){return Map.of("items",db.queryForList("SELECT * FROM categories WHERE active=true ORDER BY name"));}
 @GetMapping("/technologies") Map<String,Object> technologies(){return Map.of("items",db.queryForList("SELECT * FROM technologies WHERE active=true ORDER BY name"));}
}
